	registerInstance(t, router, map[string]any{
		"service_name": "svc", "instance_id": "fresh", "healthy": true,
		"weight": 1, "heartbeat_at": at(9),
	})

	for range 2 {
		servicesOverview(t, router,
			"/api/v1/services?evaluate_at="+at(10)+"&heartbeat_timeout=1m")
